import type { AgentSearchStatus } from '../../types/design-library';
import { MemoryUnavailable } from './memoryComponents';
import {
  EngineBusy,
  ModelCallRefused,
  type EngineBinding,
} from './MemoryModelService';
import type { MemoryRuntime } from './MemoryRuntime';

export const AGENT_COLD_START_WAIT_MS = 10_000;
export const AGENT_BUSY_WAIT_MS = 2_000;
export const AGENT_QUERY_TIMEOUT_MS = 10_000;
export const AGENT_SEARCH_BINDING: EngineBinding = {
  maxModelCalls: 0,
  queueTimeoutMs: AGENT_BUSY_WAIT_MS,
};

const engineStartStatus = (error: unknown): AgentSearchStatus =>
  error instanceof MemoryUnavailable ? error.reason : 'engine_failed';

export const startEngineForAgent = async (
  memory: Pick<MemoryRuntime, 'isReady' | 'start'>,
  {
    waitMs = AGENT_COLD_START_WAIT_MS,
    onStarted,
  }: { waitMs?: number; onStarted?: () => void } = {},
): Promise<AgentSearchStatus> => {
  if (memory.isReady) return 'ok';
  const started = memory
    .start({ isDownloadAllowed: false, ...(onStarted ? { onStarted } : {}) })
    .then((): AgentSearchStatus => 'ok', engineStartStatus);
  let timer: NodeJS.Timeout | undefined;
  const waited = new Promise<AgentSearchStatus>((resolve) => {
    timer = setTimeout(() => resolve('engine_starting'), waitMs);
  });
  try {
    return await Promise.race([started, waited]);
  } finally {
    clearTimeout(timer);
  }
};

export const agentSearchFailureStatus = (
  error: unknown,
): AgentSearchStatus | null => {
  if (error instanceof ModelCallRefused) return 'model_call_refused';
  if (error instanceof EngineBusy) return 'engine_busy';
  return null;
};
